          ]
        },
        "writing": {
          "section_name": "Writing Task",
          "tasks_verbatim": [
            {
              "task_text": "Write a paragraph about a place that you have visited which has stayed in your memory. Remember to mention: Why did you go there? Who did you travel with? How did you prepare for the travel? Where did you stay? What activities did you do there?",
              "question_bank": []
