        "beyond_text": {
          "section_name": "Learning Beyond the Text",
          "tasks_verbatim": [
            {
              "task_text": "Search for poems or songs dedicated to India, your motherland, in your regional language. Share them with your classmates and explain their meaning too.",
              "question_bank": []
            },
            {
              "task_text": "In groups of six, prepare an interdisciplinary project on India's major geographical features. For each feature, describe the region, explain its importance in the lives of the people living there and mention the languages spoken in that region. Include one example each of: Mountains (Himalayas, Western Ghats, etc.), Rivers (Ganga, Yamuna, Krishna, Kaveri, Godavari, etc.), Deserts (Thar Desert, Rann of Kutch, etc.), Valleys (Kangra Valley, Nubra Valley, etc.), Islands (Andaman and Nicobar Islands, Lakshadweep, etc.), Plateaus (Deccan, Malwa, Meghalaya, etc.).",
              "question_bank": []
